"""Explicit per-requirement assertion candidates. No test-run/pass inference.

The links below were chosen against atomic requirement text and inspected test
assertions. Repeated methods may prove distinct narrow clauses. A partial link
must never confer full atomic PASS. Independent review remains required.
"""
from pathlib import Path
import csv,json,hashlib,re
ROOT=Path(__file__).resolve().parents[1]
def rows(p):return list(csv.DictReader((ROOT/p).open(),delimiter='\t'))
cat={r['method']:r for r in rows('STAGE9_CLOSEOUT_TEST_CATALOG.tsv')}
disp={r['atomic_requirement_id']:r for r in rows('STAGE9_CLOSEOUT_DISPOSITION.tsv')}
links=[]
def bind(ids,methods,predicate,scope='direct_atomic_candidate'):
 for rid in ids.split():
  assert rid in disp,rid
  for name in methods.split():
   if name not in cat:raise ValueError(name)
   c=cat[name]
   links.append(dict(atomic_requirement_id=rid,coverage_scope=scope,test_file=c['test_file'],method=name,method_range=f"{c['start_line']}-{c['end_line']}",method_sha256=c['method_sha256'],assertion_predicate=predicate,actual_assertion_anchors=c['assertion_anchors'],execution_result='NOT_BOUND_TO_RUN',raw_result_path='',raw_result_sha256='',independent_review='PENDING'))
